import 'package:flutter/material.dart'; import '../../../core/theme/app_theme.dart'; import '../models/chatbot_models.dart';
class ChatRouteCard extends StatelessWidget { const ChatRouteCard({super.key, required this.route}); final ChatRouteResult route; @override Widget build(BuildContext context) { final values = [if (route.distanceKm != null) '${route.distanceKm!.toStringAsFixed(1)} km', if (route.durationMinutes != null) '${route.durationMinutes} min']; if (values.isEmpty) return const SizedBox.shrink(); return Card(child: Padding(padding: const EdgeInsets.all(AppTheme.spaceMd), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Route summary'), Directionality(textDirection: TextDirection.ltr, child: Text(values.join(' · ')))]))); } }
